// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivateBank, Log} from "../src/PrivateBank.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    PrivateBank c;

    function setUp() public {
        c = new PrivateBank(address(new Log()));
    }

    function testFuzz_property(uint256 deposit, uint256 amount) public {
        vm.assume(deposit <= VALUE_CAP);
        // deposit must be at least MinDeposit to credit the balance
        deposit = bound(deposit, c.MinDeposit(), type(uint96).max);
        amount = bound(amount, 0, deposit);

        address actor = address(0xBEEF);
        vm.deal(actor, deposit);

        vm.prank(actor);
        c.Deposit{value: deposit}();

        uint256 balBefore = c.balances(actor);

        vm.prank(actor);
        c.CashOut(amount);

        uint256 balAfter = c.balances(actor);

        // Reference: balAfter == balBefore - amount (decreases, cannot exceed balBefore).
        // Mutant: balAfter == balBefore + amount (increases).
        assertTrue(balAfter <= balBefore);
    }
}
